export default {"id":"spatial-level-11","number":11,"title":"Monitoring while mixing","skillBand":"Textbook","duration":"From the course textbook","summary":"— Speakers, headphones, and consumer enhancement","modules":[{"id":"spatial-m-11-1-2","code":"11.1","title":"— Speakers, headphones, and consumer enhancement","blurb":"— Speakers, headphones, and consumer enhancement","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-part-12-1","title":"Speakers, headphones, and consumer enhancement","blocks":[{"type":"step","title":"Module 11.1 — Speakers, headphones, and consumer enhancement","blocks":[{"type":"prose","html":"<strong>Outcomes.</strong> Student can state which monitor path they are using and turn consumer enhancement off for mix decisions."},{"type":"table","headers":["ID","Lesson","One-sentence job"],"rows":[["11.1.1","UMG nearfield levels","If a calibrated room exists: <strong>79 or 82 dB SPL LCS</strong> (Slow, C-weighted) is what UMG calls common. If no SPL meter, write “uncalibrated” — do not invent a phone-app number."],["11.1.2","Headphones are required in the process","UMG: incorporate headphone monitoring; binaural metadata is for headphone streaming."],["11.1.3","Processing Off","Dolby Access: disable Dolby Audio Processing when judging a mix or a master."],["11.1.4","Windows Sonic Off","Do not mix an Atmos session through Sonic “to hear it bigger.”"],["11.1.5","Direct Render 5.1 check","UMG: review a 5.1 re-render / consumer 5.1."]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> processing Off; headphone + speaker (or honest “speakers absent”).   <strong>mustNotCover:</strong> requiring 79 dB without a meter.   <strong>Primary sources:</strong> UMG Best Practices; local guide disable-processing.   <strong>Practice:</strong> mix-decision checklist taped to the path card.   <strong>Checkpoint:</strong> student can show processing Off."}]}],"minutes":8}],"exercises":[]},{"id":"spatial-m-11-2-3","code":"11.2","title":"— Binaural metadata","blurb":"— Binaural metadata","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"spatial-part-12-2","title":"Binaural metadata","blocks":[{"type":"step","title":"Module 11.2 — Binaural metadata","blocks":[{"type":"prose","html":"<strong>Outcomes.</strong> Student knows Off / Near / Mid / Far and the QC traps."},{"type":"table","headers":["ID","Lesson","One-sentence job"],"rows":[["11.2.1","What it is","Renderer distance model per object and bed channel. Headphone / binaural only — not speaker processing."],["11.2.2","Four modes","Off, Near, Mid, Far. Mid is the software default."],["11.2.3","Not automatable","UMG: cannot change on a given object over time. Reassign the object instead."],["11.2.4","All Off fails","Prohibited as a universal setting; fails technical QC."],["11.2.5","All Mid is flagged","UMG QC may flag all-Mid as neglected metadata."],["11.2.6","Dead center","Object in the exact center of the room: no binauralization; unpredictable on some speaker layouts."],["11.2.7","Dry front image","UMG suggestion: front wall + Off or Near."],["11.2.8","Gapless albums","Shared object numbers and identical binaural settings across joins."]],"caption":null},{"type":"prose","html":"<strong>mustCover:</strong> four modes; all-Off fail; all-Mid flag; not automatable.   <strong>mustNotCover:</strong> a single “correct template” presented as Dolby law (UMG says adopt <strong>a</strong> template, not a universal secret sauce).   <strong>Primary sources:</strong> UMG Best Practices (Binaural Metadata).   <strong>Practice:</strong> if a host exists, set two objects to different modes and A/B headphones. If not, write a planned template.   <strong>Checkpoint:</strong> student can explain why all-Off is a reject."}]}],"minutes":8}],"exercises":[]}]};
